      "@media (prefers-reduced-motion: reduce){.ai-gauge svg animate{display:none}.mp-agonist,.mp-synergist{animation:none !important}}",
      "/* == Step3: heat-glow breathing (opacity .85<->1, 2.4s) replaces flat look == */",
      ".mp-agonist{transform-box:fill-box;transform-origin:center;animation:mpPulseStrong 2.4s ease-in-out infinite}",
      ".mp-synergist{transform-box:fill-box;transform-origin:center;animation:mpPulseSoft 2.4s ease-in-out infinite;animation-delay:.5s}",
      "@keyframes mpPulseStrong{0%,100%{opacity:.85}50%{opacity:1}}",
      "@keyframes mpPulseSoft{0%,100%{opacity:.85}50%{opacity:.98}}",
      "@media (prefers-reduced-motion: reduce){[class*=pose-]{animation:none !important}}",
