      ".pro-toggle-label{flex:1;font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--muted);white-space:nowrap}",
      ".pro-switch{position:relative;width:82px;height:26px;border-radius:var(--r-pill);background:var(--dim);border:1px solid var(--border);cursor:pointer;flex-shrink:0;font-size:0}",
      ".pro-switch::after{content:'';position:absolute;top:2px;left:2px;width:38px;height:20px;border-radius:var(--r-pill);background:var(--primary);transition:transform .25s var(--spring)}",
      ".pro-switch .ps-simple,.pro-switch .ps-pro{position:absolute;top:50%;transform:translateY(-50%);font-size:9px;font-weight:700;letter-spacing:.03em;pointer-events:none;transition:color .2s}",
      ".pro-switch .ps-simple{left:8px;color:#fff}.pro-switch .ps-pro{right:10px;color:var(--muted)}",
