      ".rp-collapse-btn{position:absolute;left:-14px;top:50%;transform:translateY(-50%);width:28px;height:44px;border-radius:8px 0 0 8px;background:var(--card);border:1px solid var(--border);border-right:none;color:var(--muted);cursor:pointer;display:none;align-items:center;justify-content:center;font-size:14px;z-index:14}",
      "@media(min-width:769px){.rp{position:relative}.rp-collapse-btn{display:flex}body.kap-rp-collapsed .rp{width:0!important;min-width:0!important;overflow:visible;border-left:none}body.kap-rp-collapsed .rp>*:not(.rp-collapse-btn){display:none!important}body.kap-rp-collapsed .rp-collapse-btn{left:-28px}}",
      ".dot{width:5px;height:5px;border-radius:50%;background:var(--dim);transition:all .2s}",
      ".dot.on{background:var(--blue);box-shadow:0 0 5px var(--bg2);width:12px;border-radius:3px}",
      ".mt2{display:none;position:fixed;bottom:68px;right:12px;z-index:100;width:42px;height:42px;border-radius:50%;background:var(--blue);border:none;color:#000;font-size:17px;cursor:pointer;box-shadow:0 0 12px var(--bg2);align-items:center;justify-content:center}",
      ".mb{display:none;position:fixed;bottom:0;left:0;right:0;background:var(--surface);border-top:1px solid var(--border);padding:5px 8px;z-index:90}",
      ".ptabs{display:flex;gap:4px}",
      ".pt{flex:1;padding:5px 3px;border-radius:7px;border:1px solid var(--border);background:transparent;color:var(--muted);font-size:10px;text-align:center;cursor:pointer;transition:all .2s}",
      ".wikibtn{flex:1;padding:5px 3px;border-radius:7px;border:1px solid var(--yellow);background:rgba(255,215,0,.08);color:var(--yellow);font-size:10px;font-weight:600;text-align:center;cursor:pointer;transition:all .2s}",
      ".wikibtn:active{background:rgba(255,215,0,.2)}",
      "@media(max-width:768px){.rp{display:none;position:fixed;bottom:52px;left:0;right:0;width:100%;height:75vh;border-left:none;border-top:1px solid var(--border);border-radius:14px 14px 0 0;z-index:80;transform:translateY(100%);transition:transform .28s ease}.rp.on{display:flex;flex-direction:column;transform:translateY(0)}.mt2{display:flex}.mb{display:block}.lc{padding:6px 8px 56px}.topbar{padding:6px 8px}.dots{display:flex}}",
      "/* == A4 + mobile layout fix: body sizing, docked controls, no floating overlap == */",
      "@media(max-width:768px){",
