      "  }",
      "  .xbtn{font-size:clamp(11px,0.9vw,14px) !important;padding:6px 14px !important;}",
      "  .mi-en{font-size:clamp(12px,1vw,15px) !important;}",
      "  .mi-zh{font-size:clamp(11px,0.9vw,13px) !important;}",
      "  .mi-header{font-size:clamp(10px,0.85vw,12px) !important;}",
      "  .mi-item{padding:8px 16px !important;}",
      "  .mi-dot{width:22px !important;height:22px !important;}",
      "  .mbr{margin-bottom:8px !important;}",
      "  .ml{font-size:clamp(12px,1vw,15px) !important;}",
      "  .mpct{font-size:clamp(11px,0.9vw,13px) !important;}",
      "  .ri{font-size:clamp(12px,1vw,14px) !important;}",
      "  .aj{font-size:clamp(11px,0.9vw,13px) !important;}",
      "  .ar{font-size:clamp(14px,1.2vw,17px) !important;}",
      "  .as{font-size:clamp(10px,0.85vw,12px) !important;}",
      "  .fn{font-size:clamp(12px,1vw,14px) !important;}",
      "  .fm{font-size:clamp(11px,0.9vw,13px) !important;}",
      "  .tpl{font-size:clamp(10px,0.85vw,12px) !important;}",
      "  .tpt{font-size:clamp(12px,1vw,14px) !important;}",
      "  #rc,#rcz{font-size:clamp(12px,1vw,14px) !important;}",
      "  .rp-tab{font-size:clamp(11px,0.9vw,13px) !important;padding:10px 6px !important;text-overflow:clip !important;overflow:visible !important;}",
      "  .st{font-size:clamp(10px,0.85vw,12px) !important;}",
      "  .mt{font-size:clamp(15px,1.25vw,18px) !important;}",
      "  .mts{font-size:clamp(12px,1vw,14px) !important;}",
      "  .search-input{font-size:clamp(12px,1vw,15px) !important;}",
      "  .rtab{font-size:clamp(10px,0.85vw,12px) !important;padding:7px 5px !important;}",
      "  .logo-text{font-size:clamp(12px,1vw,14px) !important;}",
      "  .vcbtn{font-size:clamp(10px,0.85vw,12px) !important;padding:5px 10px !important;}",
      "  .ltoggle{font-size:clamp(10px,0.85vw,12px) !important;padding:5px 10px !important;}",
      "  .lc-label{font-size:clamp(10px,0.85vw,12px) !important;}",
      "  .vc-lc{font-size:clamp(10px,0.85vw,12px) !important;padding:6px 8px !important;}",
      "  .ll{font-size:clamp(11px,0.95vw,13px) !important;}",
      "  .layerbtn{font-size:clamp(11px,0.95vw,13px) !important;}",
      "}",
      "",
