      '<button class="vcbtn" data-gd="female"><span class="le">FEMALE</span><span class="lz" style="display:none">\u5973</span></button>',
      '<button class="vcbtn on" data-sd="front"><span class="le">FRONT</span><span class="lz" style="display:none">\u524D</span></button>',
      '<button class="vcbtn" data-sd="back"><span class="le">BACK</span><span class="lz" style="display:none">\u5F8C</span></button>',
      '<button class="ltoggle" id="ltbtn">\u4E2D / EN</button>',
