      "var POSE_ANIM={",
      "  curl:[",
      "    {slugs:['forearm','hands'],side:'left',type:'rot',originX:200,originY:506,from:0,to:-28},",
      "    {slugs:['forearm','hands'],side:'right',type:'rot',originX:530,originY:506,from:0,to:28}",
