      "};",
      "function applyPoseAnim(k){",
      "  var svg=document.getElementById('bsvg');",
      "  if(!svg) return;",
      "  svg.querySelectorAll('[data-slug]').forEach(function(el){",
      "    el.classList.remove('pose-on','pose-rot-l','pose-rot-r','pose-scale','pose-translate');",
      "    el.style.removeProperty('transform-origin');",
      "    ['--pf','--pt','--sf','--st','--tf','--tt'].forEach(function(v){el.style.removeProperty(v);});",
      "  });",
      "  var cfg=POSE_ANIM[k];",
      "  if(!cfg||vk()!=='maleFront') return;",
      "  cfg.forEach(function(seg){",
      "    seg.slugs.forEach(function(slug){",
      "      var sel='[data-slug=\"'+slug+'\"]'+((seg.side&&seg.side!=='both')?'[data-side=\"'+seg.side+'\"]':'');",
      "      svg.querySelectorAll(sel).forEach(function(el){",
      "        el.classList.remove('mp-agonist','mp-synergist');",
      "        if(seg.type==='rot'){",
      "          el.classList.add('pose-on',seg.side==='right'?'pose-rot-r':'pose-rot-l');",
      "          el.style.transformOrigin=seg.originX+'px '+seg.originY+'px';",
      "          el.style.setProperty('--pf',seg.from+'deg');",
      "          el.style.setProperty('--pt',seg.to+'deg');",
      "        } else if(seg.type==='scale'){",
      "          el.classList.add('pose-on','pose-scale');",
      "          el.style.transformOrigin=seg.originX+'px '+seg.originY+'px';",
      "          el.style.setProperty('--sf',seg.scaleFrom);",
      "          el.style.setProperty('--st',seg.scaleTo);",
      "        } else if(seg.type==='translate'){",
      "          el.classList.add('pose-on','pose-translate');",
      "          el.style.setProperty('--tf',seg.tFrom+'px');",
      "          el.style.setProperty('--tt',seg.tTo+'px');",
      "        }",
      "      });",
      "    });",
      "  });",
      "}",
      "function showModal(slug){showMIDetail(slug);}",
