      "  cobra:'<circle cx=\"44\" cy=\"18\" r=\"4.5\"/><path d=\"M 44,22 Q 30,26 14,38\" fill=\"none\"/><line x1=\"30\" y1=\"24\" x2=\"34\" y2=\"38\"/><line x1=\"14\" y1=\"38\" x2=\"14\" y2=\"44\"/>',",
      "  calf_wall:'<circle cx=\"16\" cy=\"14\" r=\"4.5\"/><line x1=\"16\" y1=\"18\" x2=\"20\" y2=\"32\"/><line x1=\"20\" y1=\"32\" x2=\"32\" y2=\"14\"/><line x1=\"20\" y1=\"32\" x2=\"18\" y2=\"50\"/><line x1=\"20\" y1=\"32\" x2=\"34\" y2=\"50\"/>',",
