      "",
      "function updateFasciaOverlay(exKey){",
      "  var active=FASCIA_MAP[exKey]||[];",
      "  ['fo-sbl','fo-sfl','fo-ll','fo-fal','fo-fl'].forEach(function(id){",
      "    var el=document.getElementById(id);",
      "    if(!el) return;",
      "    var show=active.indexOf(id)>=0;",
      "    el.style.display=show?'':'none';",
      "    if(show) el.classList.add('tense');",
      "    else el.classList.remove('tense');",
      "  });",
      "}",
      "document.getElementById('dslider').addEventListener('input',function(){document.getElementById('dval').textContent=this.value+'%';var op=parseInt(this.value)/100;document.querySelectorAll('.mp').forEach(function(p){p.style.opacity=op;});});",
      "document.getElementById('mt2').addEventListener('click',function(){pOpen=!pOpen;document.getElementById('rp').classList.toggle('on',pOpen);this.textContent=pOpen?'\\u00d7':'\\u2630';});",
      "document.querySelectorAll('.pt').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('.pt').forEach(function(x){x.classList.remove('on');});this.classList.add('on');if(!pOpen){pOpen=true;document.getElementById('rp').classList.add('on');document.getElementById('mt2').textContent='\\u00d7';}document.querySelectorAll('.rp-tab').forEach(function(rb){rb.classList.remove('on');});var aT=document.querySelector('.rp-tab[data-rpt=\"analysis\"]');if(aT)aT.classList.add('on');['ps-analysis','ps-search','ps-bodymap','ps-stretch','ps-wiki','ps-progress'].forEach(function(pid){var pe=document.getElementById(pid);if(pe)pe.style.display=pid==='ps-analysis'?'':'none';});var t=this.dataset.pt;var el=t==='analysis'?document.getElementById('atitle'):t==='arom'?document.getElementById('aromg'):t==='fascia'?document.getElementById('fasc'):document.getElementById('tplist');setTimeout(function(){if(el)el.scrollIntoView({behavior:'smooth',block:'start'});},100);})})",
      "function selectEx(key){if(!EX[key]) return;cEx=key;document.querySelectorAll('.ex-card').forEach(function(c){c.classList.toggle('on',c.dataset.ex===key);});buildAnalysis(EX[key]);document.querySelectorAll('.pt').forEach(function(x){x.classList.remove('on');});document.querySelectorAll('.pt').forEach(function(b){if(b.dataset.pt==='analysis')b.classList.add('on');});document.querySelectorAll('.rp-tab').forEach(function(b){b.classList.toggle('on',b.dataset.rpt==='analysis');});['ps-analysis','ps-search','ps-bodymap','ps-stretch','ps-wiki','ps-progress'].forEach(function(pid){var pe=document.getElementById(pid);if(pe)pe.style.display=pid==='ps-analysis'?'':'none';});pOpen=true;document.getElementById('rp').classList.add('on');}",
      "document.getElementById('mi-detail').addEventListener('click',function(e){var it=e.target.closest('.mi-usage-item');if(it&&it.dataset.exkey){selectEx(it.dataset.exkey);}});",
      "function showToast(m){var t=document.getElementById('toast');t.textContent=m;t.classList.add('on');setTimeout(function(){t.classList.remove('on');},2000);}",
      "function initStreakBadge(){",
      "  try{",
      "    var KEY='ka_streak_v1';",
      "    var today=new Date().toISOString().slice(0,10);",
      "    var data=JSON.parse(localStorage.getItem(KEY)||'{}');",
      "    var streak=data.streak||0;",
      "    var last=data.last;",
      "    if(last!==today){",
      "      if(last){var diff=Math.round((new Date(today)-new Date(last))/86400000);streak=(diff===1)?streak+1:1;}",
      "      else{streak=1;}",
      "      localStorage.setItem(KEY,JSON.stringify({streak:streak,last:today}));",
      "    }",
      "    var b=document.getElementById('streakBadge');",
      "    var n=document.getElementById('streakNum');",
      "    if(b&&n&&streak>=1){n.textContent=streak;b.style.display='flex';b.classList.add('on');}",
      "  }catch(e){}",
      "}",
      "function fireConfetti(){",
      "  try{",
      "    var colors=['#FF6B4A','#FFB84D','#14B8A6','#38BDF8','#A78BFA'];",
      "    for(var i=0;i<24;i++){",
      "      var el=document.createElement('div');",
      "      el.className='confetti-piece';",
      "      var angle=Math.random()*Math.PI*2,dist=60+Math.random()*140;",
      "      el.style.setProperty('--cx',(Math.cos(angle)*dist)+'px');",
      "      el.style.setProperty('--cy',(Math.sin(angle)*dist-40)+'px');",
      "      el.style.setProperty('--cr',(Math.random()*720-360)+'deg');",
      "      el.style.background=colors[i%colors.length];",
      "      el.style.animation='confettiFall '+(700+Math.random()*500)+'ms ease-out forwards';",
      "      document.body.appendChild(el);",
      "      (function(node){setTimeout(function(){node.remove();},1300);})(el);",
      "    }",
      "  }catch(e){}",
      "}",
      "function maybeFireUnlockConfetti(){",
      "  try{",
      "    if(!localStorage.getItem('ka_seen_muscle')){localStorage.setItem('ka_seen_muscle','1');fireConfetti();}",
      "  }catch(e){}",
      "}",
