      "}",
      "function buildLibGrid(){",
      "  var z=zh();var dq=String.fromCharCode(34);var keys=libFilteredKeys();",
      "  var grid=document.getElementById('lib-grid');",
      "  var cEl=document.getElementById('lib-count');if(cEl)cEl.innerHTML=z?('找到 <b>'+keys.length+'</b> 個動作（共 '+Object.keys(EX).length+' 個）'):('<b>'+keys.length+'</b> of '+Object.keys(EX).length+' movements');",
      "  if(!keys.length){var hasQ=!!kapNorm(KAP.libQuery);grid.innerHTML='<div class='+dq+'lib-empty'+dq+'>'+(hasQ?(z?'還沒找到這個名稱。試著用肌肉名稱，或回到身體部位慢慢找。':'Nothing matched yet. Try a muscle name, or browse by body part.'):(z?'沒有符合的動作':'No matching exercises'))+'<br><button type='+dq+'button'+dq+' class='+dq+'ka-btn'+dq+' id='+dq+'lib-clear-all'+dq+'>'+(z?'清除篩選':'Clear filters')+'</button></div>';var ca=document.getElementById('lib-clear-all');if(ca)ca.addEventListener('click',kapLibClearAll);return;}",
      "  var noteH=(keys.indexOf(cEx)<0&&kapLibFiltersActive())?'<div class='+dq+'lib-note'+dq+'>'+(z?'目前動作不在結果中；選一個結果之前，上一個／下一個仍使用完整列表。':'Your current movement is not in these results; previous/next keep using the full list until you pick one.')+'</div>':'';",
      "  grid.innerHTML=noteH+keys.map(function(k){var ex=EX[k];",
      "    var lvl='';for(var i=1;i<=3;i++)lvl+=(i<=ex.level?'\\u25CF':'\\u25CB');",
      "    var dots=(ex.muscles||[]).slice(0,3).map(function(m){return '<span class='+dq+'lib-c-dot'+dq+' style='+dq+'background:'+m.col+dq+'></span>';}).join('');",
      "    var name=ex.ten.replace(/ ANALYSIS$/i,'');var nz=ex.tzh.replace(/分析$/,'');",
      "    return '<div class='+dq+'lib-card'+(k===cEx?' on':'')+dq+' data-libex='+dq+k+dq+'>'+",
      "      '<div class='+dq+'lib-c-name'+dq+'>'+name+'</div>'+",
      "      '<div class='+dq+'lib-c-zh'+dq+'>'+nz+'</div>'+",
      "      '<div class='+dq+'lib-c-badges'+dq+'><span class='+dq+'lib-c-badge cat'+dq+'>'+(z?CAT_ZH[ex.cat]:CAT_EN[ex.cat])+'</span><span class='+dq+'lib-c-badge equip'+dq+'>'+(z?EQUIP_ZH[ex.equip]:EQUIP_EN[ex.equip])+'</span></div>'+",
      "      '<div class='+dq+'lib-c-foot'+dq+'><span class='+dq+'lib-c-level'+dq+'>'+lvl+'</span><span class='+dq+'lib-c-dots'+dq+'>'+dots+'</span></div>'+",
      "    '</div>';",
      "  }).join('');",
      "  grid.querySelectorAll('[data-libex]').forEach(function(c){c.addEventListener('click',function(){var k=this.dataset.libex;goMain(k);closeLibSheet();});});",
      "}",
      "function buildLibSheet(){buildLibFilters();var si=document.getElementById('lib-search');if(si){si.value=KAP.libQuery||'';si.placeholder=zh()?'輸入動作名稱，例如：深蹲、階梯、跑步':'Type a movement, e.g. squat, stairs, running';if(!si._kb){si._kb=1;si.addEventListener('input',function(){KAP.libQuery=this.value;kapLibSyncClear();buildLibGrid();});si.addEventListener('keydown',function(e){if(e.key==='Escape'&&this.value){this.value='';KAP.libQuery='';kapLibSyncClear();buildLibGrid();e.preventDefault();e.stopPropagation();}});}var cb=document.getElementById('lib-search-clear');if(cb&&!cb._kb){cb._kb=1;cb.addEventListener('click',function(){KAP.libQuery='';si.value='';kapLibSyncClear();buildLibGrid();si.focus();});}}kapLibSyncClear();buildLibGrid();}",
      "function openLibSheet(){if(!KAP._libTrigger)KAP._libTrigger=document.activeElement;buildLibSheet();document.getElementById('lib-sheet').classList.add('on');if(!('ontouchstart' in window)){var si=document.getElementById('lib-search');if(si)setTimeout(function(){si.focus();},60);}}",
      "function closeLibSheet(){document.getElementById('lib-sheet').classList.remove('on');var t=KAP._libTrigger;KAP._libTrigger=null;if(t&&t.focus&&document.body.contains(t))try{t.focus();}catch(e){}}",
      "var extInfoBtn=document.getElementById('ext-info-btn');if(extInfoBtn)extInfoBtn.addEventListener('click',openLibSheet);",
      "var extFindBtn=document.getElementById('ext-find');if(extFindBtn)extFindBtn.addEventListener('click',function(){KAP._libTrigger=this;openLibSheet();});",
      "function navKeys(){var ks=(typeof libFilteredKeys==='function')?libFilteredKeys():Object.keys(EX);if(ks.indexOf(cEx)<0)ks=Object.keys(EX);return ks;}",
      "var extPrevBtn=document.getElementById('ext-prev');if(extPrevBtn)extPrevBtn.addEventListener('click',function(){var ks=navKeys();var i=ks.indexOf(cEx);if(i>0)loadEx(ks[i-1]);});",
      "var extNextBtn=document.getElementById('ext-next');if(extNextBtn)extNextBtn.addEventListener('click',function(){var ks=navKeys();var i=ks.indexOf(cEx);if(i<ks.length-1)loadEx(ks[i+1]);});",
      "function updateExTitle(k){",
      "  var ex=EX[k];if(!ex)return;",
      "  var ks=navKeys();var i=ks.indexOf(k);",
      "  var en=document.querySelector('.ext-name-en');var zhEl=document.querySelector('.ext-name-zh');",
      "  if(en)en.textContent=ex.ten.replace(/ ANALYSIS$/i,'');if(zhEl)zhEl.textContent=ex.tzh.replace(/\\u5206\\u6790$/,'');",
      "  var cnt=document.getElementById('ext-count');if(cnt)cnt.textContent=(i+1)+' / '+ks.length+(ks.length<Object.keys(EX).length?(zh()?' · 篩選中':' · filtered'):'');",
      "  var badge=document.getElementById('ext-anim-badge');if(badge)badge.style.display=ANIM_EX[k]?'inline-flex':'none';",
      "  var prevBtn=document.getElementById('ext-prev');if(prevBtn)prevBtn.style.visibility=i>0?'visible':'hidden';",
      "  var nextBtn=document.getElementById('ext-next');if(nextBtn)nextBtn.style.visibility=i<ks.length-1?'visible':'hidden';",
      "}",
