      "/* accessible names / tooltips / placeholders: Chinese only */",
      "var KAP_ATTR_ZH={'Main':'主要導覽','Help':'說明','Previous':'上一個','Next':'下一個','Zoom':'縮放','Zoom out':'縮小','Zoom in':'放大','Reset zoom to 100%':'還原到 100%','Reset':'還原','Legend':'圖例','Close':'關閉','Reading depth':'閱讀方式','Exercise library':'動作庫','Clear search':'清除搜尋','Body regions':'身體部位','Collapse / Expand':'收合／展開','skeleton':'骨骼示意','KAP':'KAP','回首頁 Home':'回首頁'};",
      "function kapZhAttrs(){document.querySelectorAll('[aria-label],[title],[placeholder],[alt]').forEach(function(e){['aria-label','title','placeholder','alt'].forEach(function(a){var v=e.getAttribute(a);if(!v||!/[A-Za-z]{3,}/.test(v))return;var n=KAP_ATTR_ZH[v];",
      "  if(n===undefined){var m=v.match(/^(.*[\\u4e00-\\u9fff][^\\/]*?)\\s*\\/\\s*[A-Za-z][A-Za-z .&-]*$/);if(m)n=m[1];else{m=v.match(/^[A-Za-z][A-Za-z .&-]*\\s*\\/\\s*([^\\/]*[\\u4e00-\\u9fff][^\\/]*)$/);if(m)n=m[1];else m=v.match(/^(?:Search|Find)\\s*\\/\\s*(.+)$/);if(m)n=m[1].replace(/\\.\\.\\.$/,'…');}}",
      "  if(n!==undefined&&n!==v)e.setAttribute(a,n);});});}",
      "(function(){var t=0;function sched(){if(t)return;t=setTimeout(function(){t=0;try{kapZhAttrs();}catch(e){}},120);}",
      " if(typeof MutationObserver!=='undefined'){var go=function(){new MutationObserver(sched).observe(document.body,{childList:true,subtree:true});sched();};if(document.body)go();else document.addEventListener('DOMContentLoaded',go);}})();",
