      "var _scrollLockY=0;",
      "function lockBodyScroll(){",
      "  _scrollLockY=window.scrollY||document.documentElement.scrollTop||0;",
      "  document.body.style.position='fixed';",
      "  document.body.style.top='-'+_scrollLockY+'px';",
      "  document.body.style.left='0';",
      "  document.body.style.right='0';",
      "  document.body.style.width='100%';",
      "}",
      "function unlockBodyScroll(){",
      "  document.body.style.position='';",
      "  document.body.style.top='';",
      "  document.body.style.left='';",
      "  document.body.style.right='';",
      "  document.body.style.width='';",
      "  window.scrollTo(0,_scrollLockY);",
      "}",
      "function openMioZoom(svgHtml, legendHtml, hintText){",
      "  var zb=document.getElementById('mio-zoom-bg');",
      "  if(!zb) return;",
      "  var dq=String.fromCharCode(34);",
      "  zb.innerHTML='<div class=\"mio-zoom-wrap\">'",
      "    +'<button class=\"mio-zoom-close\" onclick=' + dq + 'closeMioZoom()' + dq + '>&#10005;</button>'",
      "    +'<div class=\"mio-zoom-stage\" id=\"mio-zoom-stage\"><div class=\"mio-zoom-inner\" id=\"mio-zoom-inner\">'+svgHtml+'</div></div>'",
      "    +'<div class=\"mio-zoom-hint\">'+(hintText||'')+'</div>'",
      "    +(legendHtml||'')",
      "    +'</div>';",
      "  zb.classList.add('on');",
      "  lockBodyScroll();",
      "  initMioZoomPan();",
      "}",
      "function closeMioZoom(){",
      "  var zb=document.getElementById('mio-zoom-bg');",
      "  if(zb) zb.classList.remove('on');",
      "  unlockBodyScroll();",
      "}",
      "function initMioZoomPan(){",
      "  var stage=document.getElementById('mio-zoom-stage');",
      "  var inner=document.getElementById('mio-zoom-inner');",
      "  if(!stage||!inner) return;",
      "  var scale=1,tx=0,ty=0,minScale=1,maxScale=6,dragging=false,lastX=0,lastY=0,moved=0;",
      "  function apply(){ inner.style.transform='translate('+tx+'px,'+ty+'px) scale('+scale+')'; }",
      "  stage.addEventListener('pointerdown',function(e){",
      "    dragging=true; lastX=e.clientX; lastY=e.clientY; moved=0;",
      "    stage.classList.add('dragging');",
      "    try{stage.setPointerCapture(e.pointerId);}catch(err){}",
      "  });",
      "  stage.addEventListener('pointermove',function(e){",
      "    if(!dragging) return;",
      "    var dx=e.clientX-lastX, dy=e.clientY-lastY;",
      "    tx+=dx; ty+=dy; moved+=Math.abs(dx)+Math.abs(dy);",
      "    lastX=e.clientX; lastY=e.clientY;",
      "    apply();",
      "  });",
      "  function endDrag(e){",
      "    dragging=false; stage.classList.remove('dragging');",
      "    if(moved<6) closeMioZoom();",
      "  }",
      "  stage.addEventListener('pointerup',endDrag);",
      "  stage.addEventListener('pointercancel',function(){dragging=false;stage.classList.remove('dragging');});",
      "  stage.addEventListener('pointerleave',function(){dragging=false;stage.classList.remove('dragging');});",
      "  stage.addEventListener('wheel',function(e){",
      "    e.preventDefault();",
      "    var rect=stage.getBoundingClientRect();",
      "    var cx=e.clientX-rect.left, cy=e.clientY-rect.top;",
      "    var factor=e.deltaY<0?1.2:1/1.2;",
      "    var ns=Math.min(maxScale,Math.max(minScale,scale*factor));",
