      "  var QBP=Object.assign({},typeof BONE_PATHS!=='undefined'?BONE_PATHS:{},typeof BONE_PATHS_2!=='undefined'?BONE_PATHS_2:{});",
      "  var mPool=Object.keys(QM).filter(function(s){return QEP[s]&&QM[s].zh;});",
      "  var bPool=Object.keys(QB).filter(function(s){return QBP[s]&&QB[s].zh;});",
      "  if(!mPool.length&&!bPool.length){wl.innerHTML='<div class=\"wiki-empty\">\u984C\u5EAB\u4E0D\u8DB3</div>';return;}",
      "  if(!window._qs) window._qs={c:0,t:0,st:0,bt:0};",
      "  var qs=window._qs;",
      "  var isBone=(bPool.length>3&&Math.random()<0.3);",
      "  var pool=isBone?bPool:mPool;",
      "  var DB=isBone?QB:QM;",
      "  var PA=isBone?QBP:QEP;",
      "  var ans=pool[Math.floor(Math.random()*pool.length)];",
      "  var rg=DB[ans].region;",
      "  var same=pool.filter(function(s){return s!==ans&&DB[s].region===rg;});",
      "  var oth=pool.filter(function(s){return s!==ans&&DB[s].region!==rg;});",
      "  function pk(a){return a.splice(Math.floor(Math.random()*a.length),1)[0];}",
      "  var wrong=[];",
      "  while(wrong.length<3&&same.length) wrong.push(pk(same));",
      "  while(wrong.length<3&&oth.length) wrong.push(pk(oth));",
      "  var opts=wrong.concat([ans]);",
      "  for(var i=opts.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=opts[i];opts[i]=opts[j];opts[j]=t;}",
      "  window._qq={ans:ans,bone:isBone,done:false};",
      "  var bp=typeof BODY_PATHS!=='undefined'?BODY_PATHS.maleFront:[];",
      "  var mi=(typeof MIDX!=='undefined')?MIDX.find(function(x){return x.slug===ans;}):null;",
      "  var col=isBone?'#e8d5b7':(mi?mi.col:'#00e5ff');",
      "  /* == v-clean ③: bone quiz uses the medical crop when available == */",
      "  var _qcrop=(isBone&&typeof kapBoneCrop==='function')?kapBoneCrop(ans):null;var s;",
      "  if(_qcrop){s='<img src=\"'+_qcrop+'\" alt=\"\" style=\"width:100%;height:100%;object-fit:contain;background:#0a1628\"/>';}else{",
      "  s='<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"-55 -91 733 1462\" preserveAspectRatio=\"xMidYMin meet\">';",
      "  s+='<rect x=\"-55\" y=\"-91\" width=\"733\" height=\"1462\" fill=\"#0a1628\"/>';",
      "  bp.forEach(function(p){var iH=(p.slug==='head'||p.slug==='hair');var f=iH?'#2c3d61':'#1a2840';var k=iH?'#4e6b99':'#2e4068';[].concat(p.common||[]).concat(p.left||[]).concat(p.right||[]).forEach(function(d){s+='<path d=\"'+d+'\" fill=\"'+f+'\" stroke=\"'+k+'\" stroke-width=\"2\"/>';});});",
      "  PA[ans].paths.forEach(function(d){s+='<path d=\"'+d+'\" fill=\"'+col+'\" stroke=\"'+col+'\" stroke-width=\"2\" opacity=\"0.92\"/>';});",
      "  s+='</svg>';}",
      "  var h='<div class=\"quiz-wrap\">';",
      "  h+='<div class=\"quiz-score\"><span>'+(z?'\u7B54\u5C0D':'Score')+' <b>'+qs.c+'</b>/'+qs.t+'</span><span>'+(z?'\u9023\u7E8C':'Streak')+' <b>'+qs.st+'</b></span><span>'+(z?'\u6700\u4F73':'Best')+' <b>'+qs.bt+'</b></span></div>';",
      "  h+='<div class=\"quiz-q\">'+(z?(isBone?'\u9019\u662F\u54EA\u4E00\u584A\u9AA8\u9ABC\uFF1F':'\u9019\u662F\u54EA\u4E00\u689D\u808C\u8089\uFF1F'):(isBone?'Which bone is this?':'Which muscle is this?'))+'</div>';",
      "  h+='<div class=\"quiz-img\">'+s+'</div>';",
      "  h+='<div class=\"quiz-opts\">';",
      "  opts.forEach(function(o){h+='<button class=\"quiz-opt\" data-slug=\"'+o+'\">'+(z?DB[o].zh:DB[o].en)+'</button>';});",
      "  h+='</div><div class=\"quiz-fb\" id=\"quiz-fb\"></div></div>';",
      "  wl.innerHTML=h;",
      "  wl.scrollTop=0;",
